  'This thread continues on {value0}. Open it there and send your next message. The copy here stays read-only for recovery.':
    'Toto vlákno pokračuje na počítači {value0}. Otevřete ho tam a odešlete další zprávu. Místní kopie zůstane jen pro čtení pro případ obnovení.',
