  '{value0} symbolic links skipped.': 'Přeskočeno symbolických odkazů: {value0}.',
  'Cancel move': 'Zrušit přesun',
  'Cancel copy': 'Zrušit kopírování',
  'Move the full saved conversation, checklist, attachments and files. Provider sessions and credentials stay here. The destination thread uses that computer’s default harness, with no more access than this thread has. Nothing runs until you send the next message there. You can change its model after it opens. This thread stays here, read-only, for recovery.':
    'Přesuňte celou uloženou konverzaci, kontrolní seznam, přílohy a soubory. Relace poskytovatelů a přihlašovací údaje zůstanou zde. Vlákno v cílovém umístění použije výchozí harness daného počítače a nebude mít větší přístupová práva než toto vlákno. Nic se nespustí, dokud tam neodešlete další zprávu. Po otevření můžete změnit jeho model. Toto vlákno zůstane zde jen pro čtení pro případ obnovení.',
  'Copy files and local Git history. The source project and chats stay here. A new folder is created on the destination. Worktrees use its configured worktree directory.':
    'Zkopírujte soubory a místní historii Gitu. Zdrojový projekt a chaty zůstanou zde. V cílovém umístění se vytvoří nová složka. Pracovní stromy použijí nakonfigurovaný adresář pracovních stromů.',
