  'Set up CuaDriver on this runtime host. CuaDriver owns OS permissions; Dovo connects agents through MCP.':
    'Nastavte CuaDriver na tomto hostiteli běhového prostředí. CuaDriver spravuje oprávnění operačního systému; Dovo připojuje agenty přes MCP.',
  'Host executable names or paths, without shell quoting. Agent overrides take precedence. New terminals use these shell settings.':
    'Názvy nebo cesty spustitelných souborů na hostiteli, bez uvozování shellu. Přepsání agenta mají přednost. Nové terminály používají tato nastavení shellu.',
