  'Enable agent computer use on this computer': 'Povolit agentům používat tento počítač',
  'Grants writable agents access to this computer’s desktop. Read-only agents are excluded. The user and agents share the desktop and app state.':
    'Udělí agentům s přístupem pro zápis přístup k ploše tohoto počítače. Agenti pouze pro čtení jsou vynecháni. Uživatelé i agenti sdílejí plochu a stav aplikací.',
  'Leave Cua Driver empty to detect it on this computer’s PATH or in its standard installation folder. Changes apply to new agent turns.':
    'Nechte Cua Driver prázdné, aby se našel v PATH tohoto počítače nebo ve standardní instalační složce. Změny se projeví při nových tazích agentů.',
  '1. Install on this computer': '1. Instalace na tomto počítači',
  'Run the official installer on the runtime host, then refresh status. It downloads and installs CuaDriver; no Cua account is required.':
    'Spusťte oficiální instalační program na hostiteli běhového prostředí a potom obnovte stav. Stáhne a nainstaluje CuaDriver; účet Cua není potřeba.',
  'Minimal Linux systems need libxi6 and at-spi2-core. GNOME needs Cua’s bundled WinRects helper; see the installation guide.':
    'Minimální systémy Linux potřebují libxi6 a at-spi2-core. GNOME potřebuje přiložený pomocný nástroj Cua WinRects; viz průvodce instalací.',
  'Install and set up Cua Driver': 'Nainstalovat a nastavit Cua Driver',
  'Detect / check Cua Driver': 'Detekovat / zkontrolovat Cua Driver',
  '2. Permissions & desktop access': '2. Oprávnění a přístup k ploše',
  '3. Agent MCP, skills & hooks': '3. MCP, dovednosti a hooky agenta',
  '4. Computer History (optional preview)': '4. Historie počítače (volitelný náhled)',
  'Grant macOS Accessibility and Screen Recording to CuaDriver and accept its relaunch. Test desktop access lists apps without changing them. Daemon controls affect active computer-use sessions.':
    'Udělte aplikaci CuaDriver oprávnění Přístupnost a Záznam obrazovky v macOS a potvrďte její restart. Test přístupu k ploše zobrazí seznam aplikací, aniž by je změnil. Ovládání démona ovlivňuje aktivní relace používání počítače.',
  'Save the computer-use switch for automatic dovo_cua MCP on new writable turns. No manual MCP registration is needed. Install the optional official skill pack; installation links detected agents on this computer.':
    'Uložte přepínač používání počítače, aby se MCP dovo_cua automaticky používalo při nových tazích agentů s přístupem pro zápis. Ruční registrace MCP není potřeba. Nainstalujte volitelnou oficiální sadu dovedností; při instalaci se propojí s rozpoznanými agenty na tomto počítači.',
  'Opt-in, encrypted, metadata-only history. Enable may restart the daemon. Disable keeps recorded data; pause temporarily stops recording. Unsupported builds report an error. Data stays on the runtime host; View recent history retrieves up to 20 events here.':
    'Historie se zapíná výslovně, je šifrovaná a obsahuje pouze metadata. Zapnutí může restartovat démona. Vypnutí ponechá zaznamenaná data; pozastavení dočasně zastaví záznam. Nepodporované sestavení zobrazí chybu. Data zůstávají na hostiteli běhového prostředí; Zobrazit nedávnou historii načte až 20 událostí.',
  'Delete recorded Computer History?': 'Smazat zaznamenanou Historii počítače?',
  'Delete all recorded history and its encryption key on this computer. This cannot be undone.':
    'Smaže se veškerá zaznamenaná historie a její šifrovací klíč v tomto počítači. Tuto akci nelze vrátit.',
