  'Switches and choices save automatically. Text fields show a Save button.':
    'Přepínače a volby se ukládají automaticky. Textová pole zobrazují tlačítko Uložit.',
  'Computer defaults apply when scoped Task lifecycle settings inherit. Scoped restart and archiving rules take precedence.':
    'Výchozí nastavení počítače platí, když jsou nastavení životního cyklu úloh pro konkrétní rozsah zděděná. Pravidla restartování a archivace pro konkrétní rozsah mají přednost.',
  'Open scoped task lifecycle': 'Otevřít životní cyklus úloh pro konkrétní rozsah',
  'Saved on this computer and shared with its paired devices. Switches and choices save automatically.':
    'Uloženo v tomto počítači a sdíleno s jeho spárovanými zařízeními. Přepínače a volby se ukládají automaticky.',
  'This computer is offline. Reconnect to load and change its preferences.':
    'Tento počítač je offline. Znovu se připojte, abyste načetli a změnili jeho předvolby.',
  'Loading computer preferences…': 'Načítání předvoleb počítače…',
  'Retry computer preferences': 'Zkusit načíst předvolby počítače znovu',
