  'Try another code': 'Zkusit jiný kód',
  'Enter address and code manually': 'Zadat adresu a kód ručně',
  'Enter the new address and a fresh pairing code from the same computer. Your saved connection stays unchanged until pairing succeeds.':
    'Zadejte novou adresu a čerstvý párovací kód ze stejného počítače. Uložené připojení zůstane nezměněné, dokud párování neproběhne úspěšně.',
  'On your computer, open Dovo and choose {value0} in Settings → Devices & runtime.':
    'V počítači otevřete Dovo a v Nastavení → Zařízení a běhové prostředí vyberte {value0}.',
  'Connect your phone': 'Připojte telefon',
  'Scan the QR code in this app to connect over the internet. No VPN or local IP needed. You can also pair using a LAN / VPN address.':
    'Naskenováním QR kódu v této aplikaci se připojíte přes internet. VPN ani místní IP adresa nejsou potřeba. Spárovat můžete také pomocí adresy LAN / VPN.',
  'Internet connection': 'Internetové připojení',
