  'This computer connection changed. Choose where to create this work again.':
    'Připojení k tomuto počítači se změnilo. Zvolte, kde chcete tuto práci znovu vytvořit.',
  'Choose another computer': 'Vybrat jiný počítač',
  'Choose where this work should run.': 'Vyberte, kde se má tato práce provádět.',
  'Shows connection details': 'Zobrazit podrobnosti připojení',
  'Reconnects. Touch and hold for details': 'Znovu se připojit. Podrobnosti zobrazíte podržením.',
  'This phone is no longer paired with a computer below. It was removed on that computer, or the runtime was reset. Pair it again from Devices in Settings.':
    'Telefon už není spárovaný s žádným z níže uvedených počítačů. Byl odebrán v daném počítači nebo bylo resetováno běhové prostředí. Spárujte ho znovu v Nastavení v části Zařízení.',
  'Connected using HTTP updates. Live streaming is reconnecting or unavailable. Reconnect to retry it.':
    'Připojeno přes aktualizace HTTP. Živé streamování se znovu připojuje nebo není dostupné. Zkuste ho obnovit opětovným připojením.',
  'Saved work stays available. Reconnect a computer to send messages or run commands there.':
    'Uložená práce zůstane dostupná. Připojením počítače v něm můžete posílat zprávy a spouštět příkazy.',
