  'Discard action': 'Zahodit akci',
  'Discard this action?': 'Zahodit tuto akci?',
  'Unsent work will be removed from this phone. Actions already applied on the computer remain applied.':
    'Neodeslaná práce bude z tohoto telefonu odstraněna. Akce, které už byly v počítači provedeny, zůstanou provedené.',
