  'Access to this computer was renewed. Some saved actions may already have run and retrying could repeat them. Check the computer before continuing. Messages keep their original delivery identity.':
    'Přístup k tomuto počítači byl obnoven. Některé uložené akce už mohly být provedeny a opakováním je můžete spustit znovu. Než budete pokračovat, zkontrolujte počítač. Zprávy si zachovají původní identitu odesílatele.',
