  'Open Dovo on your computer and keep it awake. In Settings → Devices & runtime, sign in and enable Dovo Connect. Sign in to the same account on your phone and choose Connect. No pairing code, VPN or local IP is needed for internet access.':
    'Otevřete Dovo v počítači a nechte ho probuzený. V Nastavení → Zařízení a běhové prostředí se přihlaste a povolte Dovo Connect. Přihlaste se na telefonu ke stejnému účtu a zvolte Connect. Pro přístup k internetu není potřeba párovací kód, VPN ani místní IP adresa.',
  'Direct internet connection': 'Přímé internetové připojení',
  'WebRTC + STUN connects your phone directly to the computer. Your content is end-to-end encrypted. Enabling Dovo Connect permits an encrypted relay fallback if a network blocks direct connections. The relay forwards encrypted traffic; it cannot read your content.':
    'WebRTC + STUN propojí telefon přímo s počítačem. Váš obsah je šifrovaný end-to-end. Povolením Dovo Connect umožníte záložní použití šifrovaného relay, pokud síť blokuje přímá připojení. Relay přeposílá šifrovaný provoz, ale nemůže číst váš obsah.',
  'LAN / VPN connections': 'Připojení přes LAN / VPN',
  'Pair LAN / VPN separately to prefer that connection when available. Copy the full Wi-Fi, Tailscale, NetBird, or HTTPS address shown on your computer, including its port. localhost and 0.0.0.0 are not addresses your phone can connect to.':
    'Samostatně spárujte LAN / VPN, aby se toto připojení přednostně použilo, kdykoli je dostupné. Zkopírujte celou adresu Wi-Fi, Tailscale, NetBird nebo HTTPS zobrazenou v počítači včetně portu. localhost a 0.0.0.0 nejsou adresy, ke kterým se telefon může připojit.',
  'Check your network': 'Zkontrolujte síť',
  'Use the same Wi-Fi or connect both devices to your VPN. For Wi-Fi connections, allow Dovo access to your Local Network in iPhone Settings.':
    'Použijte stejnou Wi-Fi nebo připojte obě zařízení k VPN. Při připojení přes Wi-Fi povolte Dovo přístup k místní síti v Nastavení iPhonu.',
  'Pairing codes expire after two minutes. CLI codes approve automatically; a code from the desktop may need approval there.':
    'Platnost párovacích kódů vyprší za dvě minuty. Kódy CLI se schvalují automaticky; kód z desktopové aplikace může vyžadovat schválení v počítači.',
  'Your pairing is saved. Try Reconnect before generating another code. If the address changed, choose Update connection address in this computer’s settings.':
    'Párování je uloženo. Než vygenerujete další kód, zkuste se znovu připojit. Pokud se adresa změnila, v nastavení tohoto počítače zvolte Aktualizovat adresu připojení.',
