  'Memory limit (MB)': 'Limit paměti (MB)',
  "Runs each new thread's agent, its commands and its terminals in a local Docker or Podman container. Only the checkout and the selected harness login are mounted. Running threads keep their setting.":
    'Spouští agenta každé nové konverzace, jeho příkazy a terminály v místním kontejneru Docker nebo Podman. Připojí se jen pracovní kopie a přihlášení vybraného agenta. Probíhající konverzace si nastavení ponechají.',
  'Without network access the harness cannot reach its model API unless that API runs inside the sandbox. Package installs and web requests also fail.':
    'Bez přístupu k síti se agent nedostane k API svého modelu, pokud toto API neběží uvnitř sandboxu. Instalace balíčků a webové požadavky také selžou.',
